DO $$ DECLARE r record; definition text; BEGIN FOR r IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('garage_profile','garage_reliability') LOOP definition:=pg_get_functiondef(r.oid); definition:=replace(definition,'garage_request_stats_hourly','customer_garage_request_stats_hourly'); EXECUTE definition; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.model_demand() RETURNS TABLE(model text,requests_7d bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(gm.canonical_model,public.normalise_model_id(s.model)),sum(s.requests)::bigint FROM public.customer_garage_model_stats_hourly s LEFT JOIN public.garage_models gm ON gm.garage_id=s.garage_id AND regexp_replace(gm.model,'[^A-Za-z0-9._-]','-','g')=s.model WHERE s.hour>now()-interval '7 days' GROUP BY 1 $$;
CREATE TABLE public.signup_welcome_notices (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, event_id uuid NOT NULL DEFAULT gen_random_uuid(), sent_at timestamptz);
GRANT ALL ON public.signup_welcome_notices TO service_role;
ALTER TABLE public.signup_welcome_notices ENABLE ROW LEVEL SECURITY;
COMMENT ON TABLE public.signup_welcome_notices IS 'Once-only signup action notice state. No sends until sender domain and email infrastructure are configured.';
CREATE OR REPLACE FUNCTION public.signup_welcome_eligible(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_user_id AND p.created_at<=now()-interval '10 minutes' AND NOT EXISTS(SELECT 1 FROM public.api_keys k WHERE k.user_id=p.id) AND NOT EXISTS(SELECT 1 FROM public.garages g WHERE g.operator_id=p.id) AND p.connect_page_seen_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.signup_welcome_notices n WHERE n.user_id=p.id AND n.sent_at IS NOT NULL)) $$;
REVOKE ALL ON FUNCTION public.signup_welcome_eligible(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.signup_welcome_eligible(uuid) TO service_role;